    "Estimate only, not a loan offer. Fees, taxes, insurance and lender terms are not included.": "Anggaran sahaja, bukan tawaran pinjaman. Yuran, cukai, insurans dan terma pemberi pinjaman tidak disertakan.",
    "Illustration only; actual returns vary and are not guaranteed. Taxes, inflation and fees are excluded.": "Ilustrasi sahaja; pulangan sebenar mungkin berbeza dan tidak dijamin. Cukai, inflasi dan yuran tidak termasuk.",
