    "Enter the current PDF password.": "Masukkan kata laluan PDF semasa.",
    "Choose a PDF of 200 MB or less to help protect browser memory.": "Pilih fail PDF bersaiz 200 MB atau kurang untuk membantu melindungi memori pelayar.",
    "Adding AES-256 password protection on your device…": "Menambah perlindungan kata laluan AES-256 pada peranti anda…",
