    "Trying to rebuild the PDF on your device…": "Sedang membina semula fail PDF pada peranti anda…",
    "A password-protected copy is ready. Keep both passwords safe; the original is unchanged.": "Salinan yang dilindungi kata laluan telah siap. Simpan kedua-dua kata laluan dengan selamat; fail asal tidak berubah.",
    "An unlocked copy is ready. The original is unchanged.": "Salinan yang tidak dikunci telah siap. Fail asal tidak berubah.",
    "A rebuilt copy passed a basic structure check. Open and review it; repair cannot restore missing content.": "Salinan yang dibina semula telah melepasi pemeriksaan struktur asas. Buka dan semak fail tersebut; proses pembaikan tidak dapat memulihkan kandungan yang hilang.",
    "Processing stopped. No new file was saved.": "Pemprosesan dihentikan. Tiada fail baharu disimpan.",
