    "Margins apply to every page. Rotated pages must be set to 0° first.": "Margin terpakai untuk setiap halaman. Halaman yang diputar mesti ditetapkan kepada 0° terlebih dahulu.",
    "Changing the CropBox hides content outside the page view; it does not securely delete it. Do not use this to conceal sensitive information.": "Menukar CropBox menyembunyikan kandungan di luar paparan halaman; ia tidak memadam kandungan tersebut secara selamat. Jangan gunakan kaedah ini untuk menyembunyikan maklumat sensitif.",
    "Processing stays on this device. A computer is recommended for large PDFs. Limits: 100 MB and 300 pages; actual performance depends on available memory.": "Pemprosesan dilakukan pada peranti ini. Penggunaan komputer disyorkan untuk fail PDF yang besar. Had: 100 MB dan 300 halaman; prestasi sebenar bergantung pada memori yang tersedia.",
    "Crop PDF": "Pangkas PDF",
    "Cropping PDF pages on your device…": "Memangkas halaman PDF pada peranti anda…",
