    "This PDF could not be cropped.": "PDF ini tidak dapat dipangkas.",
    "Cropped PDF copy is ready. The original is unchanged; content outside the CropBox may still be present.": "Salinan PDF yang telah dipangkas sudah sedia. Fail asal tidak berubah; kandungan di luar *CropBox* mungkin masih wujud.",
    "Choose a PDF to redact": "Pilih PDF untuk redaksi",
    "Drag over sensitive content on each page. The black areas are burned into a newly rebuilt copy; this does not merely draw a removable cover.": "Seret kursor merentasi kandungan sensitif pada setiap halaman. Kawasan hitam akan dibakar secara kekal ke dalam salinan yang dibina semula; tindakan ini bukan sekadar melukis penutup yang boleh dialih keluar.",
    "Your PDF stays on this device. Redaction rebuilds every page as an image, so text search/copy, forms, links, existing signatures, layers and accessibility structure are removed. Keep the original. A computer is recommended. Limits: 50 MB, 100 pages and a device-memory budget; the usable resolution depends on the document and device.": "PDF anda kekal pada peranti ini. Proses penyuntingan sulit (*redaction*) membina semula setiap halaman sebagai imej, jadi fungsi carian/salin teks, borang, pautan, tandatangan sedia ada, lapisan dan struktur kebolehcapaian akan dibuang. Simpan fail asal. Penggunaan komputer adalah disyorkan. Had: 50 MB, 100 halaman dan had memori peranti; resolusi yang boleh digunakan bergantung pada dokumen dan peranti.",
    "PDF page controls": "Kawalan halaman PDF",
    "Previous page": "Halaman sebelumnya",
