    "This PDF is password-protected. Use the PDF password tool with the current password, then choose the unlocked copy.": "PDF ini dilindungi kata laluan. Gunakan alat kata laluan PDF dengan kata laluan semasa, kemudian pilih salinan yang telah dibuka kuncinya.",
    "This PDF could not be opened. Keep the original and try a valid, unencrypted PDF.": "PDF ini tidak dapat dibuka. Simpan fail asal dan cuba gunakan PDF yang sah dan tidak disulitkan.",
