    "Rebuilding page": "Membina semula halaman",
    "A redacted copy is ready. The original is unchanged. The new PDF contains flattened page images, not the original PDF objects.": "Salinan yang telah disunting sudah siap. Fail asal tidak berubah. PDF baharu mengandungi imej halaman yang telah diratakan (flattened), bukan objek PDF asal.",
