    "This PDF needs too much memory at the selected resolution. Choose a lower resolution or fewer pages.": "PDF ini memerlukan terlalu banyak memori pada resolusi yang dipilih. Pilih resolusi yang lebih rendah atau bilangan halaman yang lebih sedikit.",
