    "For safety, scripts, styles, images, links, forms and external content are removed. This tool prints simple text and tables; it does not convert a website URL.": "Demi keselamatan, skrip, gaya, imej, pautan, borang dan kandungan luaran dibuang. Alat ini mencetak teks ringkas dan jadual; ia tidak menukar URL laman web.",
    "HTML content is limited to 250,000 characters. Website URLs are not fetched.": "Kandungan HTML dihadkan kepada 250,000 aksara. URL laman web tidak diambil.",
    "Choose a PDF to convert to PDF/A": "Pilih PDF untuk ditukar kepada PDF/A",
    "PDF/A-1b makes a flattened image copy of every page. Text is not searchable or selectable. Forms, links, existing signatures, metadata and accessibility structure are not retained. Keep your original.": "PDF/A-1b menghasilkan salinan imej rata bagi setiap halaman. Teks tidak boleh dicari atau dipilih. Borang, pautan, tandatangan sedia ada, metadata dan struktur kebolehcapaian tidak dikekalkan. Simpan fail asal anda.",
    "This is a visual archival copy, not an accessibility or electronic-signature copy. The browser does not run veraPDF on each file. Validate the download before relying on archival compliance.": "Ini ialah salinan arkib visual, bukan salinan untuk tujuan kebolehcapaian atau tandatangan elektronik. Pelayar tidak menjalankan veraPDF pada setiap fail. Sahkan fail yang dimuat turun sebelum bergantung padanya untuk pematuhan arkib.",
    "Output resolution": "Resolusi output",
    "I understand that this creates an image-only copy; my original file will not be changed.": "Saya faham salinan imej sahaja akan dibuat; fail asal tidak akan berubah.",
    "Create PDF/A-1b visual copy": "Cipta salinan visual PDF/A-1b",
