    "Preparing PDF/A file…": "Sedang menyediakan fail PDF/A…",
    "PDF/A-1b image copy is ready. The browser confirmed that it opens and has the expected number of pages; this file was not individually validated with veraPDF. Verify it before relying on archival compliance.": "Salinan imej PDF/A-1b telah siap. Pelayar mengesahkan bahawa fail boleh dibuka dan mempunyai bilangan halaman yang dijangkakan; fail ini tidak disahkan secara individu menggunakan veraPDF. Lakukan pengesahan sebelum bergantung padanya untuk pematuhan arkib.",
    "This PDF could not be converted to a PDF/A copy. The original file is unchanged.": "PDF ini tidak dapat ditukar kepada salinan PDF/A. Fail asal kekal tidak berubah.",
    "This PDF is processed on your device and is not uploaded. A computer is recommended for this memory-intensive conversion.": "PDF ini diproses pada peranti anda dan tidak dimuat naik. Penggunaan komputer disyorkan untuk penukaran yang banyak menggunakan memori ini.",
    "Visual edits flatten modified pages; searchable text on them is lost. Limit: 50 MB, 100 pages, 40 MP. A computer is recommended.": "Suntingan visual meratakan halaman yang diubah suai; teks yang boleh dicari padanya akan hilang. Had: 50 MB, 100 halaman, 40 MP. Penggunaan komputer disyorkan.",
    "Edit text or image": "Edit teks atau imej",
    "Drag over the area to replace, then add text or a PNG/JPEG image. A solid background hides the old content; it may not match the page. Modified pages are flattened and lose searchable text.": "Seret pada kawasan yang ingin diganti, kemudian tambah teks atau imej PNG/JPEG. Latar belakang legap akan menutup kandungan asal; ia mungkin tidak sepadan dengan halaman tersebut. Halaman yang diubah suai akan diratakan dan kehilangan keupayaan carian teks.",
