    "Office files stay on your device. Layout, formulas, charts, animations, fonts and page breaks may change. Office to PDF opens your browser’s print dialog. Use a computer for large files.": "Fail Office kekal pada peranti anda. Susun atur, formula, carta, animasi, fon dan pemisah halaman mungkin berubah. Fungsi Office ke PDF akan membuka dialog cetakan pelayar anda. Gunakan komputer untuk fail bersaiz besar.",
    "PDF to Excel estimates rows from selectable text; it does not recreate formulas or tables. PDF to PowerPoint makes image-only slides. Scanned PDFs need OCR first.": "Fungsi PDF ke Excel menganggarkan baris daripada teks yang boleh dipilih; ia tidak membina semula formula atau jadual. Fungsi PDF ke PowerPoint menghasilkan slaid yang mengandungi imej sahaja. PDF yang diimbas memerlukan OCR terlebih dahulu.",
