    "Optimize PDF (keep text & layout)": "Optimumkan PDF (kekalkan teks dan susun atur)",
    "Strong compression (pages become images)": "Mampatan kuat (halaman menjadi imej)",
    "PDFs are processed on this device, never uploaded. Compression has no fixed file-size cap; available memory and browser support are the practical limits.": "Fail PDF diproses pada peranti ini dan tidak dimuat naik. Pemampatan tidak mempunyai had saiz fail tetap; had praktikalnya bergantung pada memori yang tersedia dan sokongan pelayar.",
    "Best first try: rewrites and recompresses PDF structure without turning pages into images. Text and layout usually remain, but not every special feature is guaranteed; editing a signed PDF may invalidate its signature. It may not get smaller.": "Cuba dahulu: menulis semula dan memampatkan struktur PDF tanpa menjadikan halaman sebagai imej. Teks dan susun atur biasanya kekal, tetapi ciri khas tidak dijamin; penyuntingan boleh membatalkan tandatangan dan fail mungkin tidak menjadi lebih kecil.",
    "Review this before continuing": "Semak sebelum meneruskan",
    "Every page is rebuilt as an image. Text will no longer be searchable or selectable; links, forms, annotations, accessibility structure and signatures will not be preserved. Small text or fine details may look worse, and the file can even grow. Always compare the result and keep your original.": "Setiap halaman dibina semula sebagai imej. Teks tidak lagi boleh dicari atau dipilih; pautan, borang, anotasi, kebolehcapaian dan tandatangan tidak dikekalkan. Teks kecil mungkin kurang jelas dan saiz fail boleh bertambah. Bandingkan hasil dan simpan fail asal.",
    "I understand these trade-offs and will keep the original.": "Saya faham kesan ini dan akan menyimpan fail asal.",
    "Image quality": "Kualiti imej",
    "Balanced · clearer text": "Seimbang · teks lebih jelas",
    "Smaller file · lower detail": "Fail lebih kecil · kurang perincian",
    "Cancel": "Batal",
    "PDF compression canceled. No new file was saved.": "Pemampatan PDF dibatalkan. Tiada fail baharu disimpan.",
    "Optimizing PDF structure on your device…": "Mengoptimumkan struktur PDF pada peranti anda…",
    "Rendering page {current} of {total} on your device…": "Memproses paparan halaman {current} daripada {total} pada peranti anda…",
    "Creating the compressed PDF on your device…": "Menghasilkan PDF termampat pada peranti anda…",
    "This method did not make the PDF smaller. The original is unchanged. Try the other mode.": "Kaedah ini tidak mengecilkan saiz PDF. Fail asal tidak berubah. Cuba mod yang lain.",
    "PDF optimization made the file {size} smaller. Compare it before using it. Your original is unchanged.": "Pengoptimuman PDF menjadikan fail {size} lebih kecil. Bandingkan fail tersebut sebelum menggunakannya. Fail asal anda tidak berubah.",
    "Image compression made the file {size} smaller. Inspect readability; the original is unchanged.": "Pemampatan imej menjadikan fail {size} lebih kecil. Periksa kualiti hasilnya; fail asal tidak diubah.",
    "Choose a video": "Pilih video",
    "The video is processed on your device and is never uploaded. There is no fixed file-size cap; available memory, storage and browser codecs set practical limits.": "Video diproses pada peranti anda dan tidak dimuat naik. Tiada had saiz fail yang tetap; had praktikal ditentukan oleh memori, storan dan kodek pelayar yang tersedia.",
    "MP4 · broadly compatible": "MP4 · keserasian meluas",
