    "Up to 1080p": "Sehingga 1080p",
    "Up to 720p": "Sehingga 720p",
    "Before you start": "Sebelum anda bermula",
    "Compression re-encodes video and may reduce quality. If a format cannot keep an audio, subtitle or data track, processing stops instead of silently removing it. Your original is never changed.": "Pemampatan mengekod semula video dan mungkin mengurangkan kualiti. Jika sesuatu format tidak dapat mengekalkan trek audio, sari kata atau data, pemprosesan akan terhenti dan bukannya membuang trek tersebut secara senyap. Fail asal anda tidak akan diubah.",
    "This browser cannot save the result as a stream, so it will temporarily use device memory. Very large videos may exceed what the browser or device can handle.": "Pelayar ini tidak dapat menyimpan hasil sebagai strim, jadi ia akan menggunakan memori peranti buat sementara waktu. Video yang sangat besar mungkin melebihi kapasiti pengendalian pelayar atau peranti.",
