    "Compressed video is {size} smaller. Review it before sharing; your original is unchanged.": "Video yang dimampatkan adalah {size} lebih kecil. Semak video tersebut sebelum berkongsi; fail asal anda tidak berubah.",
    "This video could not be made smaller. No copy was saved; your original is unchanged. Try a lower quality or resolution.": "Video ini tidak dapat dikecilkan saiznya. Tiada salinan disimpan; fail asal anda tidak berubah. Cuba kualiti atau resolusi yang lebih rendah.",
    "Video compression canceled. No compressed copy was kept.": "Pemampatan video dibatalkan. Tiada salinan termampat disimpan.",
