    "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG or ICO. Animated files export their first frame. Metadata is not copied.": "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG atau ICO. Fail animasi mengeksport bingkai pertamanya. Metadata tidak disalin.",
    "Transparent areas become white. Animated images use only their first frame.": "Kawasan lutsinar bertukar menjadi putih. Imej beranimasi hanya menggunakan bingkai pertamanya.",
    "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG and ICO. Animated files export only their first frame. Output up to 40 megapixels.": "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG dan ICO. Fail beranimasi hanya mengeksport bingkai pertamanya. Output sehingga 40 megapiksel.",
    "Convert common image formats to JPG, PNG or WebP on your device. Up to 20 files.": "Tukar format imej biasa kepada JPG, PNG atau WebP pada peranti anda. Sehingga 20 fail.",
    "Add up to 20 images. No fixed file-size cap; 20 megapixels per image. Large batches depend on your device memory.": "Tambah sehingga 20 imej. Tiada had saiz fail tetap; 20 megapiksel setiap imej. Pemprosesan kelompok besar bergantung pada memori peranti anda.",
    "Images converted. Animated files become a still frame; metadata is not copied.": "Imej telah ditukar. Fail beranimasi menjadi bingkai pegun; metadata tidak disalin.",
    "Some files were skipped. Use a supported image format within the on-page limits.": "Sesetengah fail telah dilangkau. Gunakan format imej yang disokong dalam had yang ditetapkan pada halaman ini.",
    "This image could not be decoded by your browser. Try another file or browser.": "Imej ini tidak dapat dinyahkod oleh pelayar anda. Cuba fail atau pelayar lain.",
    "Choose a supported image format.": "Pilih format imej yang disokong.",
    "The browser does not support the selected output format.": "Pelayar tidak menyokong format output yang dipilih.",
    "Up to 20 images · 20 megapixels per image · no fixed file-size cap. Large batches depend on your device memory.": "Sehingga 20 imej · 20 megapiksel setiap imej · tiada had saiz fail tetap. Pemprosesan kelompok besar bergantung pada memori peranti anda.",
    "Choose up to 20 images.": "Pilih sehingga 20 imej.",
    "AVIF and some HEIC files may depend on browser support.": "Fail AVIF dan sesetengah fail HEIC mungkin bergantung pada sokongan pelayar.",
    "AVIF and some HEIC inputs depend on browser support. Animated GIF, APNG and WebP files become a still image. SVG is rasterized, not converted into an editable vector. Metadata is not copied.": "Input AVIF dan sesetengah input HEIC bergantung pada sokongan pelayar. Fail GIF, APNG dan WebP beranimasi menjadi imej pegun. SVG dirasterkan, bukan ditukar menjadi vektor yang boleh disunting. Metadata tidak disalin.",
    "Multi-page TIFF uses only its first page. Some TIFF compression variants may not decode.": "TIFF berbilang halaman hanya menggunakan halaman pertamanya. Sesetengah varian pemampatan TIFF mungkin tidak dapat dinyahkod.",
    "Choose a DOCX, XLSX or PPTX file": "Pilih fail DOCX, XLSX atau PPTX",
    "Files stay on your device. Limits: 100 MB input, 200 MB expanded data and 5,000 package parts.": "Fail kekal pada peranti anda. Had: input 100 MB, data dikembangkan 200 MB dan 5,000 bahagian pakej.",
    "This safely recompresses the Office package without rewriting its contents. Embedded photos are not recompressed, so the result may not be smaller. Signed, encrypted, macro-enabled and older Office files are not supported. Keep your original.": "Ini memampatkan semula pakej Office dengan selamat tanpa menulis semula kandungannya. Foto terbenam tidak dimampatkan semula, jadi hasilnya mungkin tidak lebih kecil. Fail Office yang ditandatangani, disulitkan, didayakan makro dan versi lama tidak disokong. Simpan fail asal anda.",
    "Try to reduce file size": "Cuba kurangkan saiz fail",
    "Processing runs locally in this browser. No upload.": "Pemprosesan dijalankan secara setempat dalam pelayar ini. Tiada muat naik.",
    "Recompressing the Office package on your device…": "Memampatkan semula pakej Office pada peranti anda…",
