    "Check the selected file and settings, then try again.": "Semak fail dan tetapan yang dipilih, kemudian cuba lagi.",
    "Up to 200 files; 100 MB total or expanded. ZIP64 and password-protected files are not supported. Large archives use device memory; a computer is recommended.": "Sehingga 200 fail; jumlah saiz 100 MB (sama ada saiz asal atau selepas dinyahzip). Fail ZIP64 dan fail yang dilindungi kata laluan tidak disokong. Arkib bersaiz besar menggunakan memori peranti; penggunaan komputer adalah disyorkan.",
    "Convert / trim": "Tukar / potong",
    "Estimate only, not a loan offer. Fees, taxes, insurance and lender terms are not included.": "Anggaran sahaja, bukan tawaran pinjaman. Yuran, cukai, insurans dan terma pemberi pinjaman tidak disertakan.",
    "Illustration only; actual returns vary and are not guaranteed. Taxes, inflation and fees are excluded.": "Ilustrasi sahaja; pulangan sebenar mungkin berbeza dan tidak dijamin. Cukai, inflasi dan yuran tidak termasuk.",
    "Website design,1,500\nHosting,12,10": "Reka bentuk laman web,1,500\nHos,12,10",
