    "Role · Company · dates&#10;What you did and achieved": "Peranan · Syarikat · tarikh&#10;Apa yang anda lakukan dan capai",
    "Choose a portrait image.": "Pilih imej potret.",
    "Remove the background from a portrait and save a transparent PNG on your device.": "Buang latar belakang daripada imej potret dan simpan sebagai PNG lutsinar pada peranti anda.",
