    "No comparison changes found.": "Tiada perubahan perbandingan ditemui.",
    "Extract selectable PDF text into Markdown with page headings. Scanned pages must be OCR-processed first; page layout and tables are not preserved.": "Ekstrak teks PDF yang boleh dipilih kepada format Markdown berserta tajuk halaman. Halaman yang diimbas perlu diproses menggunakan OCR terlebih dahulu; susun atur halaman dan jadual tidak dikekalkan.",
    "Extracts selectable text page by page. Scanned pages need OCR first; layout, tables and images are not preserved. Your file stays on this device.": "Mengekstrak teks yang boleh dipilih mengikut halaman. Halaman yang diimbas memerlukan proses OCR terlebih dahulu; Susun atur, jadual dan imej tidak dikekalkan. Fail anda kekal pada peranti ini.",
    "Markdown conversion complete. Review the extracted text and download the file.": "Penukaran Markdown selesai. Semak teks yang diekstrak dan muat turun fail tersebut.",
