    "Use different passwords, and keep them somewhere safe. If you lose them, this tool cannot recover them.": "Gunakan kata laluan yang berbeza dan simpan di tempat yang selamat. Jika anda kehilangannya, alat ini tidak dapat memulihkannya.",
    "This removes encryption only when you know the current password. It does not bypass or guess passwords.": "Ini membuang penyulitan hanya jika anda mengetahui kata laluan semasa. Ia tidak memintas atau meneka kata laluan.",
    "Processing uses this device and a local PDF engine. The engine is downloaded only when you start. Files are not uploaded. A computer is recommended for large PDFs; this page accepts files up to 200 MB to help protect browser memory.": "Pemprosesan menggunakan peranti ini dan enjin PDF setempat. Enjin dimuat turun hanya apabila anda bermula. Fail tidak dimuat naik. Penggunaan komputer disyorkan untuk fail PDF yang besar; halaman ini menerima fail sehingga 200 MB bagi membantu melindungi memori pelayar.",
    "Choose a PDF that will not open": "Pilih PDF yang tidak dapat dibuka",
    "This makes a best-effort rebuilt copy and checks that a PDF reader can parse it. It cannot restore missing or destroyed page data, and some files cannot be repaired.": "Ini menghasilkan salinan binaan semula yang terbaik dan menyemak sama ada pembaca PDF boleh memprosesnya. Ia tidak dapat memulihkan data halaman yang hilang atau musnah, dan sesetengah fail tidak dapat dibaiki.",
    "The repair runs on this device. Nothing is uploaded. The local engine is downloaded only when you start. For large files, use a computer. The maximum input is 200 MB to help protect browser memory. Keep your original.": "Proses pembaikan dijalankan pada peranti ini. Tiada apa-apa yang dimuat naik. Enjin setempat dimuat turun hanya apabila anda bermula. Untuk fail besar, gunakan komputer. Had input maksimum ialah 200 MB bagi membantu melindungi memori pelayar. Simpan fail asal anda.",
